const base=new URL('../',import.meta.url),url=new URL(location.href),senate=url.searchParams.get('typ')==='senat'||url.pathname.endsWith('/senat.html');
url.pathname=base.pathname;if(senate){url.searchParams.set('typ','senat');url.searchParams.set('kolo',url.searchParams.get('kolo')==='2'?'2':'1');}else{url.searchParams.set('typ','komunal');url.searchParams.delete('kolo');}history.replaceState(null,'',url);
async function boot(){if(senate){const r=await fetch(new URL('senat.html',base),{credentials:'same-origin'});if(!r.ok)throw Error('Senátní šablona HTTP '+r.status);const doc=new DOMParser().parseFromString(await r.text(),'text/html'),main=doc.querySelector('main');if(!main)throw Error('Chybí senátní šablona.');document.querySelector('main').replaceChildren(...main.children);document.title='Senátní volby 2026';await import('./views/senate.js');}else{document.title='Komunální volby 2026';await import('./app.js');await import('./views/search.js');await import('./views/metadata.js');const menu=document.getElementById('election-menu'),search=document.getElementById('search-form')?.closest('section');if(menu&&search)menu.after(search);}await import('./views/location-ui.js');await import('./views/top-navigation.js');}
boot().catch(e=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='Spuštění aplikace selhalo: '+e.message;document.querySelector('main').append(p);console.error(e);});
